changeSet.sql:
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_call_state CHECK (call_state IN ('OPEN', 'SETTLED', 'ENDED'));
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_open_call
    CHECK (call_state <> 'OPEN' OR (run_id IS NOT NULL AND lease_epoch IS NOT NULL));
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_model_kind
    CHECK (model_kind IN ('CHAT', 'DECISION', 'EMBEDDING', 'RERANKING'));
ALTER TABLE llm_usage_event ADD CONSTRAINT sfk_llm_usage_event_run FOREIGN KEY (run_id, workspace_id)
    REFERENCES agent_run (id, workspace_id) ON DELETE SET NULL (run_id);
CREATE INDEX idx_llm_usage_unpriced ON llm_usage_event (occurred_at, id)
    WHERE pricing_state = 'UNPRICED' AND measurement_verification = 'VERIFIED' AND unreported_calls = 0;
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_initial_price
    CHECK (initial_pricing_state IN ('PRICED', 'NO_CHARGE', 'UNPRICED'));
CREATE FUNCTION guard_usage_call_transition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.initial_pricing_state IS DISTINCT FROM OLD.initial_pricing_state THEN
   RAISE EXCEPTION 'A model call keeps its initial pricing state' USING ERRCODE = '23514';
 END IF;
 IF NEW.call_state = OLD.call_state
    OR (OLD.call_state = 'OPEN' AND NEW.call_state IN ('SETTLED', 'ENDED'))
    OR (OLD.call_state = 'SETTLED' AND NEW.call_state = 'ENDED') THEN
   RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Illegal usage call transition: % -> %', OLD.call_state, NEW.call_state USING ERRCODE = '23514';
END $$;
CREATE TRIGGER llm_usage_event_guards_call_transition BEFORE UPDATE ON llm_usage_event
 FOR EACH ROW EXECUTE FUNCTION guard_usage_call_transition();
CREATE FUNCTION settle_agent_run_calls() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 UPDATE llm_usage_event
    SET call_state = 'SETTLED', measurement_verification = 'UNVERIFIABLE', pricing_state = 'UNPRICED',
        cost_usd = NULL, unreported_calls = 1
  WHERE run_id = OLD.id AND workspace_id = OLD.workspace_id AND call_state = 'OPEN';
 RETURN OLD;
END $$;
CREATE TRIGGER agent_run_settles_calls BEFORE DELETE ON agent_run
 FOR EACH ROW EXECUTE FUNCTION settle_agent_run_calls();
